import type { Metadata } from "next";
import { siteConfig } from "./site";
import { defaultLocale, localizedPath, type Locale } from "./i18n/config";

/**
 * The site-wide share card generated by `src/app/opengraph-image.tsx`. Kept as a
 * constant so pages that build their own `openGraph` block (posts with a cover)
 * have one obvious thing to fall back to.
 */
export const DEFAULT_OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: siteConfig.title,
} as const;

/**
 * Build page metadata from the shared site defaults. `path` is the logical,
 * locale-agnostic path ("/blog"); `locale` decides the canonical URL and the
 * OpenGraph locale. Every page gets `hreflang` alternates for both languages
 * plus an `x-default` pointing at English.
 */
export function buildMetadata({
  title,
  description = siteConfig.description,
  path = "/",
  locale = defaultLocale,
}: {
  title?: string;
  description?: string;
  path?: string;
  locale?: Locale;
}): Metadata {
  const canonical = localizedPath(locale, path);

  return {
    title,
    description,
    alternates: {
      canonical,
      languages: {
        en: localizedPath("en", path),
        ru: localizedPath("ru", path),
        "x-default": localizedPath("en", path),
      },
      // Each locale advertises its own feed, not the English one.
      types: {
        "application/rss+xml": localizedPath(locale, "/feed.xml"),
      },
    },
    openGraph: {
      title: title ? `${title} · ${siteConfig.name}` : siteConfig.title,
      description,
      url: canonical,
      siteName: siteConfig.name,
      locale: locale === "ru" ? "ru_RU" : "en_US",
      type: "website",
      // Setting `openGraph` at all replaces the root segment's file-based card,
      // so it has to be named explicitly or every page built through here shares
      // with a blank preview. Relative — `metadataBase` (root layout) absolutises it.
      images: [DEFAULT_OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: title ? `${title} · ${siteConfig.name}` : siteConfig.title,
      description,
      images: [DEFAULT_OG_IMAGE.url],
    },
  };
}
